INSERT INTO categories (id, name, title, intro, image, is_honey, sort, version, updated_at, updated_by) VALUES
  ('comb-honey', 'Comb Honey', 'Comb Honey', 'Single-flower and seasonal honeys, packed with a piece of real honeycomb in every box. Each one tastes of the flowers the bees visited: drumstick blossoms, sunflower fields, mustard in winter bloom, coriander, or a whole season of wildflowers.', 'cat-comb.jpg', 1, 1, 1, '2026-11-15T00:00:00Z', 'seed'),
  ('blossom-honey', 'Blossom Honey', 'Blossom Honey', 'Single-flower honeys, each from one kind of bloom: coffee flowers in the shade of forest trees, the lilac karanji tree, litchi orchards in spring and fields of flowering tulasi. Every jar tastes of its flower.', 'cat-blossom.jpg', 1, 2, 1, '2026-11-15T00:00:00Z', 'seed'),
  ('wild-rare', 'Wild & Rare', 'Wild & Rare', 'Honey from bees nobody keeps and flowers nobody plants: the stingless dammar bee that stores honey in tiny resin pots, the dwarf honey bee that hangs a single comb from a wild branch, and the Neela Kurinji hills of the Western Ghats. Harvests are small and seasonal.', 'cat-wild.jpg', 1, 3, 1, '2026-11-15T00:00:00Z', 'seed'),
  ('from-the-hive', 'From the Hive', 'From the Hive', 'Pure beeswax candles that burn clean with a soft honey scent, and 10 g honey sticks for tea, tiffin boxes, travel and return gifts.', 'honey-sticks-box.jpg', 0, 4, 1, '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (1, 'murungai-honey', 'MUR', 'live', 1, 'Murungai Honey', 'comb-honey', 'Monofloral', 'With honeycomb', 1, 'Gathered from the blossoms of the drumstick tree.', '#EEF0D6', 'murungai-main.jpg', NULL, '[["Source","Drumstick tree flowers"],["Colour","Amber"],["Taste","Mild, lightly herbal"],["Texture","Thick and smooth"]]', 4, 5, 'Murungai honey is gathered by bees from the small cream-white flowers of the drumstick tree, found in almost every Tamil home garden. It is amber in colour, with a mild sweetness and a light herbal note. Moringa blooms only in certain seasons, so this single-flower honey comes in limited batches, with a piece of raw honeycomb in every box.', '["Single-flower honey from moringa blossoms","Mild taste the whole family enjoys","A natural source of quick energy","Real honeycomb in the box: raw and edible"]', NULL, 'Stir a spoonful into warm water in the morning, drizzle over dosa or chapati, or add to herbal kashayam once it has cooled a little.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["mild","herbal"],"uses":["daily","remedy"]}', '[1,2,3,4]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (2, 'multifloral-honey', 'MUL', 'live', 2, 'Multifloral Honey', 'comb-honey', 'Multifloral', 'With honeycomb', 1, 'A taste of every flower in the season.', '#F7E3E6', 'multifloral-main.jpg', NULL, '[["Source","Wildflowers, fruit trees, crops"],["Colour","Light amber to amber"],["Taste","Balanced and floral"],["Texture","Smooth and flowing"]]', 4, 5, 'Multifloral honey is made when bees visit many kinds of flowers in the same season: wildflowers, fruit trees and field crops. No two harvests taste exactly alike, and that is part of its charm. It has a balanced sweetness and a pleasant floral aroma, which makes it the everyday honey for the whole family.', '["Nectar from many flowers in one box","Everyday honey for the whole family","Use it in place of sugar in drinks and sweets","Real honeycomb in the box: raw and edible"]', NULL, 'Add to tea, lemon juice and milkshakes, spread on bread, or pour over a bowl of fruit.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["floral","mild"],"uses":["daily","kids"]}', '"all"', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (3, 'forest-honey', 'FOR', 'live', 3, 'Forest Honey', 'comb-honey', 'Wild harvest', 'With honeycomb', 1, 'Wild honey from deep forest hives.', '#DCE7E0', 'forest-main.jpg', NULL, '[["Source","Wild forest trees and flowers"],["Colour","Amber to dark amber"],["Taste","Bold, rich, slightly woody"],["Texture","Thick"]]', 5, 6, 'Forest honey comes from wild hives that bees build high in trees and on rock faces deep inside the forest, most often by the giant rock bee. The nectar comes from countless wild trees and flowers that no farm can grow. The result is a dark, thick honey with a bold, rich flavour and a slightly woody finish, harvested by hand in small batches.', '["Nectar from wild, uncultivated forest","Strong, full-bodied taste for honey lovers","Hand-harvested in small batches","Wild honeycomb in every box"]', NULL, 'Best straight from the spoon, or stirred into warm water with ginger and pepper on cold days.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["rich"],"uses":["daily","remedy"]}', '[3,4,5,6]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (4, 'sunflower-honey', 'SUN', 'live', 4, 'Sunflower Honey', 'comb-honey', 'Monofloral', 'With honeycomb', 1, 'Bright gold, from fields of sunflowers.', '#D3E5EF', 'sunflower-main.jpg', NULL, '[["Source","Sunflower fields"],["Colour","Bright golden yellow"],["Taste","Mild, fruity, lightly tangy"],["Texture","Sets soft and creamy"]]', 3, 4, 'Sunflower honey is made from the nectar of sunflower fields in full bloom. It has a sunny golden colour, a mild fruity sweetness and a light tang. It crystallises quickly and naturally, often within a few weeks, turning soft and creamy. That is a sign of real, unprocessed honey, not spoilage.', '["Sunny colour and a light, fruity taste","Sets naturally into a spreadable cream","Kids love it on bread and chapati","Real honeycomb in the box: raw and edible"]', NULL, 'Spread on toast or chapati. To make it runny again, stand the closed box in warm water for 10 to 15 minutes.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["mild","floral"],"uses":["kids","daily"]}', '[1,2,3]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (5, 'mustard-honey', 'MUS', 'live', 5, 'Mustard Honey', 'comb-honey', 'Monofloral', 'With honeycomb', 1, 'Creamy white honey from yellow mustard fields.', '#E6E5F0', 'mustard-honey-jar.jpg', NULL, '[["Source","Mustard fields"],["Colour","Pale gold, sets creamy white"],["Taste","Mild, with a gentle sharp finish"],["Texture","Thick and creamy"]]', 1, 2, 'Mustard honey comes from the bright yellow mustard fields that bloom across North India in winter. Fresh from the hive it is pale gold, but within days it sets into a thick, creamy, almost white honey that spreads like butter. The taste is mild and smooth, with a faint sharpness at the end from the mustard plant.', '["Sets into a smooth, spreadable cream","Mild taste with a gentle sharp finish","No drips: easy for lunch boxes","Real honeycomb in the box: raw and edible"]', NULL, 'Spread on bread, dosa or chapati, or stir into warm milk. Setting solid is natural and does not mean the honey has gone bad.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["mild"],"uses":["kids","daily"]}', '[12,1,2]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (6, 'coriander-honey', 'COR', 'live', 6, 'Coriander Honey', 'comb-honey', 'Monofloral', 'With honeycomb', 1, 'Aromatic honey with a gentle spice note.', '#DCEBE6', 'coriander.jpg', NULL, '[["Source","Coriander flowers"],["Colour","Golden amber"],["Taste","Aromatic, hints of citrus and spice"],["Texture","Smooth, may set creamy"]]', 4, 5, 'Coriander honey is made from the tiny white and pale pink flowers of the coriander plant, grown for its seeds in Rajasthan and Madhya Pradesh. It is golden amber, with a warm, aromatic flavour and light notes of citrus and spice. Over time it may set into a soft cream, which is natural for raw honey.', '["Unique aroma from coriander blossoms","Warm, slightly spicy finish","Pairs well with herbal tea and lemon","Real honeycomb in the box: raw and edible"]', NULL, 'Stir into herbal or green tea once it cools a little, or drizzle over curd and fruit.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["herbal","floral"],"uses":["daily","remedy"]}', '[1,2,3]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (7, 'native-honey', 'NAT', 'live', 7, 'Native Honey', 'comb-honey', 'Burrow · Native bee', 'With honeycomb', 1, 'From India’s own native honey bee.', '#DDE6EF', 'native-honey-jar.jpg', NULL, '[["Bee","Indian honey bee"],["Colour","Light amber to amber"],["Taste","Fresh, sweet, gentle tang"],["Texture","Light and flowing"]]', 4, 5, 'Native honey comes from the Indian honey bee, which has lived alongside our farms and villages for generations and nests in hollows and burrows. Native bees forage on local flowers close to the hive, so the honey carries the true taste of the land around it. It is usually lighter in body, with a fresh sweetness and a gentle tang.', '["From the indigenous Indian honey bee","Local flowers, the true taste of the land","Supports native bee-keeping","Native honeycomb in every box"]', NULL, 'An everyday honey: take a spoon in warm water, or use it in place of sugar in drinks and home remedies.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["mild"],"uses":["remedy","daily"]}', '"all"', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (8, 'forest-coffee-honey', 'FCO', 'live', 8, 'Forest Coffee Honey', 'blossom-honey', 'Monofloral', 'Single-flower honey', 0, 'From coffee flowers in the shade of forest trees.', '#EADFD3', 'coffee-jar.jpg', NULL, '[["Source","Coffee flowers under forest shade"],["Colour","Light amber to amber"],["Taste","Caramel with soft fruity notes"],["Texture","Smooth, velvety body"]]', 4, 5, 'Forest coffee honey comes from the white blossoms of coffee plants growing in the shade of tall forest trees. The coffee bushes flower for only a few days after the first rains, filling the grove with a jasmine-like scent, and the bees work the flowers while they last. The honey is light amber to amber, with caramel and soft fruity notes. It does not taste of coffee; it tastes of the flowers.', '["Honey from coffee blossoms in shaded forest groves","Caramel sweetness with a soft, fruity finish","A short flowering season makes every batch special","Lovely in black tea and over warm toast"]', NULL, 'Stir into black tea or a cold coffee, drizzle over pancakes and toast, or enjoy a spoonful on its own.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["rich","floral"],"uses":["daily","kids"]}', '[2,3,4]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (9, 'karanji-honey', 'KAR', 'live', 9, 'Karanji Honey', 'blossom-honey', 'Monofloral', 'Single-flower honey', 0, 'From the lilac blossoms of the karanji tree.', '#ECDDEF', 'karanji-trees.jpg', NULL, '[["Source","Karanji (pungai) tree flowers"],["Colour","Amber to dark amber"],["Taste","Rich, with a gentle sharp finish"],["Texture","Thick and smooth"]]', 5, 6, 'Karanji honey is gathered from the flowers of the karanji tree, known in Tamil as pungai, a hardy shade tree that grows along roads, farm edges and village tanks. When it blooms, the tree is covered in clusters of lilac and white flowers that bees visit from morning to evening. The honey is amber to dark amber, with a rich, full taste and a gentle sharp finish.', '["Single-flower honey from karanji blossoms","Rich, full taste with a gentle bite","From a hardy tree of Indian villages","Lovely with ginger and lemon in warm water"]', NULL, 'Mix with ginger and lemon in warm water, or stir into herbal kashayam once it has cooled a little.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["rich","herbal"],"uses":["remedy","daily"]}', '[3,4,5]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (10, 'litchi-honey', 'LIT', 'live', 10, 'Litchi Honey', 'blossom-honey', 'Monofloral', 'Single-flower honey', 0, 'Floral honey from litchi orchards in bloom.', '#F5DEDA', 'litchi-orchard.jpg', NULL, '[["Source","Litchi flowers"],["Colour","Extra light amber to light amber"],["Taste","Floral and gently fruity"],["Texture","Smooth, may set creamy"]]', 3, 4, 'Litchi honey is made when bees visit the small, creamy flowers of litchi trees, a few months before the fruit ripens. The orchards bloom for a short season, so the harvest is quick and seasonal. It is light amber, with a floral, gently fruity taste and an aroma that recalls the litchi blossom itself. Like many light honeys, it can set into a soft cream over time, which is natural.', '["Single-flower honey from litchi orchards","Light, floral and gently fruity","Mild enough for the whole family","Turns plain curd and fruit into a dessert"]', NULL, 'Drizzle over curd, fruit salad or pancakes, or stir into lemon juice and iced tea.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["floral","mild"],"uses":["kids","daily"]}', '[2,3]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (11, 'tulasi-honey', 'TUL', 'live', 11, 'Tulasi Honey', 'blossom-honey', 'Monofloral', 'Single-flower honey', 0, 'Honey from the blossoms of holy basil.', '#E1E9D6', 'tulasi-bees.jpg', NULL, '[["Source","Tulasi (holy basil) flowers"],["Colour","Amber to dark amber"],["Taste","Sweet, with a soft herbal note"],["Texture","Thick and smooth"]]', 5, 6, 'Tulasi honey comes from bees that forage on the small purple-white flower spikes of tulasi, the holy basil grown in courtyards and fields across India. Tulasi flowers through a long part of the year, and the bees visit it steadily. The honey is amber to dark amber, sweet with a soft herbal, slightly peppery note that carries a hint of the plant itself.', '["Single-flower honey from tulasi blossoms","Sweet, with a soft herbal note","Made for warm drinks on cool mornings","A thoughtful gift for the family"]', NULL, 'Stir into warm water with a few tulasi leaves and a slice of ginger, or add to herbal tea once it has cooled a little.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["herbal"],"uses":["remedy","daily"]}', '"all"', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (12, 'dammar-honey', 'DAM', 'live', 12, 'Dammar Honey', 'wild-rare', 'Stingless bee', 'Rare · Small harvests', 0, 'Tiny bees, rare honey, a tangy taste.', '#EEDCC7', 'dammar-main.jpg', NULL, '[["Bee","Stingless dammar bee"],["Colour","Amber to dark brown"],["Taste","Sweet-sour and tangy"],["Texture","Thin and runny"]]', 4, 6, 'Dammar honey is made by tiny stingless bees that store their honey in small pots of wax and plant resin instead of combs. A single colony gives only a few hundred grams a year, which makes it one of the rarest honeys in India. It is thin and runny, with a distinct sweet-sour taste and a resin aroma that comes from the hive itself.', '["From stingless dammar bees","Very small harvests: a truly rare honey","Distinct sweet-sour taste and resin aroma","Prized in traditional home remedies"]', NULL, 'Take half to one teaspoon at a time, on its own or in lukewarm water.', 'Close tightly and keep in a cool place. Refrigerate after opening to keep it fresh longer.', '{"taste":["herbal"],"uses":["remedy"],"rare":true}', '"all"', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (13, 'kombu-honey', 'KOM', 'live', 13, 'Kombu Honey', 'wild-rare', 'Wild · Dwarf honey bee', 'Wild harvest', 0, 'From single combs hanging on wild branches.', '#E8E0D0', 'kombu-main.jpg', NULL, '[["Bee","Dwarf honey bee"],["Colour","Light amber to amber"],["Taste","Rich wildflower taste"],["Harvest","Small, seasonal, wild"]]', 4, 5, 'Kombu honey is a wild honey made by the dwarf honey bee, the smallest honey bee in India. These bees build a single palm-sized comb that hangs from a thin branch (kombu) in bushes and small trees. Each comb holds only a little honey, so it is collected from the wild in very small quantities. It has a rich, distinct wildflower taste.', '["From the wild dwarf honey bee","Collected from single combs in the wild","Small, seasonal harvests","A traditional favourite in Tamil homes"]', NULL, 'Take a spoonful on its own, or mix with warm water in the morning.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["rich"],"uses":["remedy","daily"],"rare":true}', '[2,3,4,5]', NULL, 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (14, 'neela-kurinji-honey', 'NEE', 'live', 14, 'Neela Kurinji Honey', 'wild-rare', 'Rare hill bloom', 'Rare · Small batches', 0, 'Honey from the blue hills of the Western Ghats.', '#E3E5F2', 'kurinji-main.jpg', NULL, '[["Source","Neelakurinji and hill flowers"],["Region","Western Ghats hills"],["Taste","Delicate and floral"],["Harvest","Rare, very small batches"]]', NULL, NULL, 'Neela Kurinji honey comes from the hills of the Western Ghats, where the Neelakurinji shrub turns whole slopes blue when it flowers. The shrub blooms together only about once every twelve years, so honey from these hills is rare and comes in very small batches. It has a delicate, floral taste that is best enjoyed simply.', '["Honey from the Neelakurinji hills of the Western Ghats","A rare harvest that comes in very small batches","Delicate, floral taste","A special gift for honey lovers"]', NULL, 'Enjoy it straight from the spoon to taste it at its best, or drizzle a little over fruit or curd. Keep it away from heat so the delicate flavour stays.', 'Store at room temperature with the lid closed. Always use a dry spoon.', '{"taste":["floral"],"uses":["gift","daily"],"rare":true}', '[8,9,10]', 'Blooms together only about once every twelve years', 1, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (15, 'beeswax-candles', 'BWC', 'live', 15, 'Beeswax Candles', 'from-the-hive', 'From the hive', 'Paraffin-free · Pollution-free', 0, 'Natural light, without the pollution.', '#F3E4C6', 'candles-trio.jpg', NULL, '[["Material","Pure beeswax"],["Burn","Clean, very little smoke"],["Scent","Light natural honey"],["Best for","Pooja, dining, gifting"]]', NULL, NULL, 'Our candles are made from pure beeswax, the natural wax bees make to build their honeycomb. Unlike paraffin candles, which come from petroleum, they burn slowly and cleanly with very little smoke, giving a warm golden glow and a soft honey scent with no added fragrance.', '["Made from pure beeswax","No paraffin, no chemicals","Burns longer than ordinary candles","Ideal for pooja, dining and gifting"]', 'Candle care', 'Trim the wick to about 5 mm before lighting and keep away from breeze. A white bloom on the surface is natural; wipe it with a soft cloth.', 'Never leave a burning candle unattended. Keep away from children and pets.', NULL, NULL, NULL, 0, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
INSERT INTO products (id, slug, short_code, status, sort, name, category, kind, badge, with_comb, tagline, tone, photo, card_photo, specs_json, colour_min, colour_max, about, love_json, use_head, use_text, store_text, finder_json, bloom_json, bloom_note, in_gift_box, first_live_at, version, created_at, updated_at, updated_by) VALUES
  (16, 'honey-sticks', 'HST', 'live', 16, 'Honey Sticks', 'from-the-hive', 'Single-serve sachets', '10 g per stick', 0, 'One stick, one serving, no mess.', '#FBE6C0', 'sticks-cup.jpg', NULL, '[["Net weight","10 g per stick"],["Serving","About 1½ teaspoons"],["Box","10 sticks (100 g)"],["Inside","Natural honey"]]', NULL, NULL, 'Honey sticks are single-serve sachets with exactly 10 g of honey, about one and a half teaspoons. No spoon, no sticky jar, no spills: tear the top and squeeze. Keep a few in your handbag, school bag, gym kit or travel pouch for a quick natural sweet whenever you need one. They also make a neat return gift for functions.', '["Exactly 10 g per stick, no measuring","Tear, squeeze, enjoy: no spoon needed","Right amount for a cup of tea or coffee","Easy to carry anywhere"]', NULL, 'Squeeze into tea, coffee or lemon water, or take it straight after a workout.', 'Store in a cool, dry place away from direct sunlight.', NULL, NULL, NULL, 0, '2026-11-15T00:00:00Z', 1, '2026-11-15T00:00:00Z', '2026-11-15T00:00:00Z', 'seed');
